query:
mutation CompleteDraftOrder($id: ID!, $sourceName: String, $paymentPending: Boolean) {
  draftOrderComplete(id: $id, sourceName: $sourceName, paymentPending: $paymentPending) {
    draftOrder {
      id
      name
      status
      order {
        id
        name
        createdAt
        displayFinancialStatus
        displayFulfillmentStatus
        purchasingEntity {
          __typename
          ... on Customer {
            id
            displayName
            defaultEmailAddress {
              emailAddress
            }
            defaultPhoneNumber {
              phoneNumber
            }
            defaultAddress {
              formatted(withCompany: true)
            }
          }
          ... on PurchasingCompany {
            company {
              id
              name
            }
            contact {
              id
              customer {
                id
                displayName
              }
            }
            location {
              id
              name
            }
          }
        }
        shippingAddress {
          ...AddressFields
        }
        lineItems(first: 50) {
          pageInfo {
            hasNextPage
          }
          nodes {
            id
            name
            quantity
            originalUnitPriceSet {
              ...MoneyBagFields
            }
            discountedTotalSet {
              ...MoneyBagFields
            }
          }
        }
        subtotalPriceSet {
          ...MoneyBagFields
        }
        totalDiscountsSet {
          ...MoneyBagFields
        }
        totalShippingPriceSet {
          ...MoneyBagFields
        }
        totalTaxSet {
          ...MoneyBagFields
        }
        totalPriceSet {
          ...MoneyBagFields
        }
        taxesIncluded
        note
        paymentTerms {
          id
          paymentTermsName
          paymentTermsType
          dueInDays
          overdue
        }
      }
    }
    userErrors {
      field
      message
    }
  }
}

fragment MoneyBagFields on MoneyBag {
  shopMoney {
    amount
    currencyCode
  }
  presentmentMoney {
    amount
    currencyCode
  }
}

fragment AddressFields on MailingAddress {
  formatted(withCompany: true)
  address1
  address2
  city
  company
  country
  countryCodeV2
  firstName
  lastName
  phone
  province
  provinceCode
  zip
}
